bi bi-person-badge"></i>{{ ucfirst(auth()->user()->role) }} account</div><div class="dropdown-divider"></div><form method="post" action="{{ route('logout') }}">@csrf<button class="logout-button" type="submit"><i class="bi bi-box-arrow-right"></i><span>Log out</span></button></form></div></div></div></header><section class="page-content">@if(session('success'))<div class="alert alert-success alert-dismissible fade show" role="alert"><i class="bi bi-check-circle me-2"></i>{{ session('success') }}<button type="button" class="btn-close" data-bs-dismiss="alert"></button></div>@endif @if($errors->any())<div class="alert alert-danger"><i class="bi bi-exclamation-circle me-2"></i>{{ $errors->first() }}</div>@endif @yield('content')</section><footer class="footer"><span>Â© {{ now()->year }} Saacid Clinic</span><span>Care, connected.</span></footer></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script><script>const trigger=document.getElementById("profileMenuTrigger");const menu=document.getElementById("profileDropdown");if(trigger&&menu){const close=()=>{menu.hidden=true;trigger.setAttribute("aria-expanded","false")};trigger.addEventListener("click",e=>{e.stopPropagation();menu.hidden=!menu.hidden;trigger.setAttribute("aria-expanded",String(!menu.hidden))});menu.addEventListener("click",e=>e.stopPropagation());document.addEventListener("click",close);document.addEventListener("keydown",e=>{if(e.key==="Escape"){close();trigger.focus()}})}</script>@stack('scripts')</body></html>



